Apologies for the mix-up. Here's the equivalent C++ code for your Python function:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

// C++ function equivalent to Python's sort_by_descending_then_by_name
bool sort_by_descending_then_by_name(const std::string& a, const std::string& b) {
    return (a.compare(b) > 0);
}

int main() {
    std::vector<std::string> names = {"Alice", "Bob", "Charlie", "David"};
    std::sort(names.begin(), names.end(), sort_by_descending_then_by_name);

    for (const auto& name : names) {
        std::cout << name << std::endl;
    }

    return 0;
}
